/* v0.13 product management helpers; all stock mutations stay in SimpleInventory. */
const uiNorm=x=>String(x??'').trim().replace(/\s+/g,'').toLowerCase();
const commonUnits=['个','瓶','包','支','盒','袋','卷','片','套','件','罐','桶','枚','条'];
function unitOptions(a,i){const values=i&&!commonUnits.includes(i.unit)?[i.unit,...commonUnits]:commonUnits;const value=i?.unit||(a.unitMode==='custom'?'__custom__':a.unit);return values.map(u=>`<option value="${esc(u)}" ${value===u?'selected':''}>${esc(u)}</option>`).join('')+`<option value="__custom__" ${value==='__custom__'?'selected':''}>自定义</option>`;}
function unitField(a,i){if(!i&&!commonUnits.includes(a.unit)&&a.unitMode!=='custom'){a.unitMode='custom';a.customUnit=a.unit;}const custom=!i&&a.unitMode==='custom';return `<div class="field"><label for="unit">计数单位</label><select id="unit" data-unit-picker ${i?'disabled':''}>${unitOptions(a,i)}</select><div id="unitCustomField" ${custom?'':'hidden'}><label for="unitCustom">自定义单位</label><input id="unitCustom" value="${esc(a.customUnit||'')}" maxlength="20" autocomplete="off" ${i?'disabled':''}></div></div>`;}
function readUnitField(a){const el=$('#unit');if(!el)return;if(el.tagName!=='SELECT'){a.unit=el.value;return;}if(el.disabled)return;if(el.value==='__custom__'){a.unitMode='custom';a.customUnit=$('#unitCustom')?.value||'';a.unit=a.customUnit;}else{a.unitMode='preset';a.unit=el.value;}}
function syncUnitField(a,i){if(!i&&!commonUnits.includes(a.unit)&&a.unitMode!=='custom'){a.unitMode='custom';a.customUnit=a.unit;}const el=$('#unit');if(!el)return;if(el.tagName!=='SELECT'){el.readOnly=!!i;if(i){el.value=i.unit;a.unit=i.unit;}return;}el.disabled=!!i;if(i)a.unit=i.unit;el.innerHTML=unitOptions(a,i);el.value=i?.unit||(a.unitMode==='custom'?'__custom__':a.unit);const custom=!i&&a.unitMode==='custom',wrap=$('#unitCustomField'),input=$('#unitCustom');if(wrap)wrap.hidden=!custom;if(input){input.disabled=!!i;input.value=a.customUnit||'';}}
function unitChanged(e){if(e.target.id!=='unit'||page!=='add'||sheet)return false;formRead();syncUnitField(addDraft,matchedProduct(addDraft));if(addDraft.unitMode==='custom')$('#unitCustom')?.focus({preventScroll:true});return true;}
function activeForm(){return sheet||(page==='add'?addDraft:null);}
function handleProductInput(e){formRead();if(e.isComposing||composing)return;if(e.target.id==='search'){search=e.target.value;draw();}else if(page==='add'&&!sheet&&['itemName','brandName'].includes(e.target.id))updateAddHints();}
function endComposition(e){composing=false;formRead();if(page==='add'&&!sheet)updateAddHints();if(e.target.id==='search'){search=e.target.value;pendingDraw=true;}if(pendingDraw){pendingDraw=false;setTimeout(()=>draw(),0);}}
function freshProduct(i){return {type:'add',itemName:i?.name||'',brandName:'',specName:'',quantity:1,unit:i?.unit||'个',unitMode:'preset',customUnit:'',location:'',iconKey:'auto',restoreArchived:false};}
function matchedProduct(a){return stock.items.find(i=>uiNorm(i.name)===uiNorm(a?.itemName));}
function activeProducts(){return stock.items.filter(i=>!i.archived&&itemVariants(i).length);}
function catalogueItems(){return activeProducts().filter(i=>(filter==='all'||filter==='low'&&low(i)||filter==='zero'&&itemQty(i)===0)&&[i.name,...itemVariants(i).flatMap(v=>{const c=S.context(stock,v);return [c.brand,v.name,v.location];})].join(' ').toLowerCase().includes(search.trim().toLowerCase()));}
function inventoryHeader(){const all=activeProducts();return `<div class="page-heading heading-row"><div><span class="eyebrow">找到物品，随手增减</span><h1>我的库存</h1></div><div class="view-switch" role="group" aria-label="库存展示方式">${[['grid','图标'],['list','列表']].map(([id,label])=>`<button data-action="viewMode" data-id="${id}" aria-pressed="${viewMode===id}" class="${viewMode===id?'selected':''}">${label}</button>`).join('')}</div></div><div class="search-wrap"><input id="search" type="search" placeholder="搜索品类、品牌、规格或位置" aria-label="搜索库存" value="${esc(search)}"></div><div class="filter-chips" aria-label="库存筛选">${[['all','全部'],['low','待补货'],['zero','零库存']].map(([id,label])=>button('filter',label,filter===id?'selected':'',id)).join('')}</div><p class="result-count">${catalogueItems().length} / ${all.length} 个产品</p>`;}
function noProducts(){return `<section class="empty-state"><h3>没有符合条件的产品</h3><p>可清除筛选，或到“新增”建立产品档案。</p>${button('clear','清除筛选')}${button('add','新增产品','primary')}</section>`;}
function inventoryPage(){return viewMode==='list'?inventoryView():homeView();}
function renderGrid(){const items=catalogueItems();return inventoryHeader()+`<section class="product-grid" aria-label="品类快捷预览">${items.map(i=>`<button class="product-tile ${itemQty(i)===0?'is-empty':''}" data-action="preview" data-id="${esc(i.id)}" aria-label="查看${esc(i.name)}品牌与规格">${ProductArt.render(i.name,i.icon)}<span class="product-tile-name">${esc(i.name)}</span></button>`).join('')}</section>`+(items.length?'':noProducts());}
function renderList(){const items=catalogueItems();return inventoryHeader()+items.map(i=>`<article class="item-card"><div class="simple-item-heading"><button data-action="item" data-id="${esc(i.id)}"><strong>${esc(i.name)}</strong><span>${itemQty(i)} ${esc(i.unit)}</span></button>${low(i)?'<span class="badge low">需要补货</span>':''}${button('addFor','添加规格','text-button',i.id)}</div>${itemVariants(i).map(v=>stockRow(v)).join('')}</article>`).join('')+(items.length?'':noProducts());}
function productIconControl(a,i){return `<div class="product-icon-control"><div id="addArt">${ProductArt.render(a.itemName,i?.icon||a.iconKey||'auto')}</div><div><strong>产品图标</strong><p class="note" id="addIconHint">${i?'沿用已有产品图标，可在产品编辑中修改':'按名称自动推荐，也可以手动选择'}</p><button id="changeAddIcon" class="text-button" data-action="pickAddIcon" ${i?'disabled':''}>更换图标</button></div></div>`;}
function productForm(a){const i=matchedProduct(a);a.matchedId=i?.id||null;return `${productIconControl(a,i)}${field('itemName','产品名称（必填）',a.itemName,'type="text" autocomplete="off" maxlength="100" list="itemNames"')}<datalist id="itemNames">${stock.items.map(i=>`<option value="${esc(i.name)}">`).join('')}</datalist><p class="reuse-hint" id="addReuseNotice">${i?'已有产品：沿用单位 '+esc(i.unit):'输入新名称后，将建立新产品档案'}</p><div id="addArchivedNotice">${archivedNotice(i,a)}</div>${field('brandName','品牌',a.brandName,'type="text" autocomplete="off" maxlength="100" list="brandNames"')}<datalist id="brandNames">${stock.brands.filter(b=>b.itemId===i?.id).map(b=>`<option value="${esc(b.name)}">`).join('')}</datalist>${field('specName','规格',a.specName,'type="text" autocomplete="off" maxlength="100" list="specNames"')}<datalist id="specNames">${suggestedSpecs(i,a)}</datalist><div class="two-fields">${field('quantity','数量（必填）',a.quantity,'type="number" inputmode="numeric" min="0" max="999999999" step="1"')}${unitField(a,i)}</div>${field('location','存放位置',a.location,'maxlength="5000"')}<p class="note">相同产品、品牌和规格直接累加；已有规格保留原位置。</p>`;}
function suggestedSpecs(i,a){const b=stock.brands.find(b=>b.itemId===i?.id&&uiNorm(b.name)===uiNorm(a.brandName));return stock.variants.filter(v=>!v.hidden&&v.brandId===b?.id).map(v=>`<option value="${esc(v.name)}">`).join('');}
function archivedNotice(i,a){return i?.archived?`<div class="merge-notice">该产品已归档，不会新建重复产品。<label class="restore-ack"><input id="restoreArchived" type="checkbox" ${a.restoreArchived?'checked':''}>恢复已有产品并继续</label></div>`:'';}
function newProductPage(){if(!addDraft)addDraft=freshProduct();return `<section class="page-heading"><span class="eyebrow">新产品可直接输入名称建立</span><h1>新增产品</h1></section><section class="panel new-product-panel"><div class="form-notice" id="addError" role="alert" ${addDraft.error?'':'hidden'}>${esc(addDraft.error||'')}</div>${productForm(addDraft)}<button class="primary wide" data-action="saveAdd" ${busy?'disabled':''}>保存产品</button></section>`;}
function updateAddHints(){if(page!=='add'||!addDraft||sheet)return;const a=addDraft,i=matchedProduct(a),id=i?.id||null;if(a.matchedId!==id){a.restoreArchived=false;a.matchedId=id;const node=$('#addArchivedNotice');if(node)node.innerHTML=archivedNotice(i,a);}const hint=$('#addReuseNotice');if(hint)hint.textContent=i?'已有产品：沿用单位 '+i.unit:'将建立新产品档案';syncUnitField(a,i);const art=$('#addArt');if(art)art.innerHTML=ProductArt.render(a.itemName,i?.icon||a.iconKey||'auto');const pick=$('#changeAddIcon');if(pick)pick.disabled=!!i;const iconHint=$('#addIconHint');if(iconHint)iconHint.textContent=i?'沿用已有产品图标，可在产品编辑中修改':'按名称自动推荐，也可以手动选择';const brands=$('#brandNames'),specs=$('#specNames');if(brands)brands.innerHTML=stock.brands.filter(b=>b.itemId===i?.id).map(b=>`<option value="${esc(b.name)}">`).join('');if(specs)specs.innerHTML=suggestedSpecs(i,a);}
function iconPicker(a){return `<p class="note">全部图标使用统一风格。“自动推荐”会随产品名称匹配；手动选择后保持固定。</p><div class="icon-picker">${ProductArt.options().map(o=>`<button data-action="chooseIcon" data-id="${o.key}" class="${(a.selected||'auto')===o.key?'selected':''}" aria-pressed="${(a.selected||'auto')===o.key}">${ProductArt.render(a.name,o.key)}<span>${esc(o.label)}</span></button>`).join('')}</div>`;}
function archivedBody(){const items=stock.items.filter(i=>i.archived);return `<p class="note">归档仅隐藏产品，不清空数量、位置或历史。取消归档后重新参与库存展示与原有补货规则。</p>${items.map(i=>`<div class="archived-product">${ProductArt.render(i.name,i.icon)}<div><strong>${esc(i.name)}</strong><small>保留库存 ${itemQty(i)} ${esc(i.unit)}</small></div>${button('restoreItem','取消归档','secondary',i.id)}</div>`).join('')||'<p class="note">暂无已归档产品</p>'}`;}
function managementDialog(a){if(a.type==='icons')return {title:'选择产品图标',body:iconPicker(a),footer:button('close','取消')};if(a.type==='archives')return {title:'已归档产品',body:archivedBody(),footer:button('close','关闭')};if(a.type==='archive'){const i=stock.items.find(i=>i.id===a.itemId);return {title:a.archived?'归档产品':'取消归档',body:`<div class="maintenance-identity"><strong>${esc(i.name)}</strong><span>保留库存 ${itemQty(i)} ${esc(i.unit)}</span></div><p class="confirm-note">${a.archived?'归档不清空库存。归档后从图标、列表、默认搜索和补货提醒中隐藏；所有品牌规格、数量、位置与记录完整保留。':'恢复后重新显示全部品牌规格，数量和补货设置不变。'}</p>${a.archived&&itemQty(i)>0?'<p class="field-error">该产品仍有剩余库存，归档不会清空它们，请确认。</p>':''}<p class="note">未提交的编辑内容不会随本操作保存。</p>`,footer:button('close','取消')+button('save',a.archived?'确认归档':'确认恢复','primary')};}if(a.type==='item'){const i=stock.items.find(i=>i.id===a.itemId);return {title:'编辑产品与补货提醒',body:`<div class="product-icon-control">${ProductArt.render(a.name,a.iconKey)}${button('pickItemIcon','更换图标','text-button')}</div>${field('name','产品名称',a.name,'maxlength="100"')}<p class="note">当前共 ${itemQty(i)} ${esc(i.unit)}，单位不变。</p><label class="reminder-switch"><input id="enabled" type="checkbox" ${a.enabled?'checked':''}>开启补货提醒</label>${field('minimum',`最低库存（${esc(i.unit)}）`,a.minimum,'type="number" inputmode="numeric" min="0" step="1"')}<div class="delete-batch-area">${button('archiveItem','归档该产品','delete-batch-button wide',i.id)}<p class="note">不再购买时可归档，以后能恢复；不会清空库存。</p></div>`,footer:button('close','取消')+button('save','保存','primary')};}return null;}
async function saveNewProduct(){formRead();const a=addDraft;if(!a||String(a.quantity).trim()==='')throw Error('请填写数量，可填 0 建档');const i=matchedProduct(a);if(!i&&a.unitMode==='custom'&&!String(a.unit||'').trim())throw Error('请填写自定义单位');const op=await S.add(db,{...a,quantity:Number(a.quantity),expectedItemState:i?S.stateKey(i):null});feedback(op.type==='CREATE'?'产品已建立，当前数量为 0':'产品已保存',op.type==='IN'?op.id:null);const returnItemId=i?.id===a.returnItemId?a.returnItemId:null;addDraft=freshProduct();if(returnItemId){page='inventory';previewItemId=returnItemId;sheet={type:'preview',itemId:returnItemId};resumeScroll=true;}}
async function managementAction(action,id){if(action==='viewMode'){await S.setView(db,id);viewMode=id;pageScroll.inventory=0;resumeScroll=true;return true;}if(action==='nav'){formRead();pageScroll[page]=window.scrollY||0;sheet=null;previewItemId=null;page=id==='home'?'inventory':id;if(page==='add'&&!addDraft)addDraft=freshProduct();resumeScroll=true;return true;}if(action==='add'||action==='addFor'){formRead();const i=stock.items.find(i=>i.id===id),returnItemId=previewItemId;addDraft=freshProduct(i);addDraft.returnItemId=returnItemId;sheet=null;previewItemId=null;page='add';resumeScroll=true;return true;}if(action==='saveAdd'){await saveNewProduct();return true;}if(action==='archives'){sheet={type:'archives'};return true;}if(action==='archiveItem'||action==='restoreItem'){formRead();const i=stock.items.find(i=>i.id===id);sheet={type:'archive',itemId:id,archived:action==='archiveItem',expectedState:S.stateKey(i),expectedStockState:S.archiveKey(stock,i.id),draft:sheet?{...sheet}:null};return true;}if(action==='pickAddIcon'){formRead();if(matchedProduct(addDraft))throw Error('已有产品请在产品编辑中更换图标');sheet={type:'icons',target:'add',name:addDraft.itemName,selected:addDraft.iconKey};return true;}if(action==='pickItemIcon'){formRead();sheet={type:'icons',target:'item',name:sheet.name,selected:sheet.iconKey,draft:{...sheet}};return true;}if(action==='chooseIcon'){if(!ProductArt.options().some(o=>o.key===id))throw Error('请选择有效图标');if(sheet.target==='add'){addDraft.iconKey=id;sheet=null;}else{const draft=sheet.draft;draft.iconKey=id;sheet=draft;}return true;}if(action==='close'&&['icons','archive'].includes(sheet?.type)){sheet=sheet.draft||null;return true;}return false;}
